    '111:1': 'تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ',
  };

  /// Returns the clean, authentic Arabic text for the given ayah.
  ///
  /// If the ayah matches one of the 102 corrupted verses (or contains `U+FFFD`),
  /// the verified clean text from [_repairedAyahs] is returned.
  /// Otherwise, [rawText] is returned directly with zero overhead.
  static String getRepairedText(int surahNumber, int ayahNumber, String rawText) {
    final key = '$surahNumber:$ayahNumber';
    final repaired = _repairedAyahs[key];
    if (repaired != null) {
      return repaired;
    }

    // Fallback: if rawText contains U+FFFD but wasn't in the static map, strip U+FFFD
    if (rawText.contains('\uFFFD')) {
      return rawText.replaceAll('\uFFFD', '');
    }

    return rawText;
  }

  /// Returns true if the ayah at [surahNumber]:[ayahNumber] is one of the known
  /// corrupted ayahs in legacy databases.
  static bool isCorrupted(int surahNumber, int ayahNumber) {
    return _repairedAyahs.containsKey('$surahNumber:$ayahNumber');
  }

  /// Total count of repaired ayahs.
  static int get repairedCount => _repairedAyahs.length;
}
